static long Score(CTCTavernGameCardBlackjack& g, CCardHand& h, const long* v, int n, CTavernCard* cards, CTavernCard** ptrs)
{
    for (int i = 0; i < n; ++i) { cards[i].m_value = v[i]; ptrs[i] = &cards[i]; }
